'use strict';

const assert = require('node:assert');
const api = require('./solution');

assert.deepStrictEqual(Reflect.ownKeys(api), ['buildLegend']);
assert.strictEqual(typeof api.buildLegend, 'function');
assert.deepStrictEqual(api.buildLegend([]), []);

const entries = Object.freeze([
  Object.freeze({ label: 'Warning', symbol: '!' }),
  Object.freeze({ label: 'Information', symbol: 'i', extra: true })
]);
const result = api.buildLegend(entries);
assert.deepStrictEqual(result, [
  { text: 'Warning', icon: '!' },
  { text: 'Information', icon: 'i' }
]);
assert.notStrictEqual(result[0], entries[0]);
assert.notStrictEqual(result[1], entries[1]);

const again = api.buildLegend(entries);
assert.notStrictEqual(again, result);
assert.notStrictEqual(again[0], result[0]);
result[0].text = 'changed';
result.push({ text: 'extra', icon: '?' });
assert.deepStrictEqual(api.buildLegend(entries), [
  { text: 'Warning', icon: '!' },
  { text: 'Information', icon: 'i' }
]);

for (const invalid of [
  null, undefined, {}, 'entries',
  [null], [[]], [{}],
  [{ label: '', symbol: 'x' }],
  [{ label: 'x', symbol: '' }],
  [{ label: 1, symbol: 'x' }],
  [{ label: 'x', symbol: 1 }]
]) {
  assert.throws(() => api.buildLegend(invalid), TypeError);
}

